self.serialize = function(){

	var data = [];
	// 0 - nodes
	// 1 - edges
	// 2 - labels
	// 3 - UID

	// Nodes
	var nodes = [];
	for(var i=0;i<self.nodes.length;i++){
		var node = self.nodes[i];
		// 0 - id
		// 1 - x
		// 2 - y
		// 3 - init value
		// 4 - label
		// 5 - hue
		nodes.push([
			node.id,
			Math.round(node.x),
			Math.round(node.y),
			node.init,
			encodeURIComponent(encodeURIComponent(node.label)),
			node.hue
		]);
	}
	data.push(nodes);

	// Edges
	var edges = [];
	for(var i=0;i<self.edges.length;i++){
		var edge = self.edges[i];
		// 0 - from
		// 1 - to
		// 2 - arc
		// 3 - strength
		// 4 - rotation (optional)
		var dataEdge = [
			edge.from.id,
			edge.to.id,
			Math.round(edge.arc),
			edge.strength
		];
		if(dataEdge.f==dataEdge.t){
			dataEdge.push(Math.round(edge.rotation));
		}
		edges.push(dataEdge);
	}
	data.push(edges);

	// Labels
	var labels = [];
	for(var i=0;i<self.labels.length;i++){
		var label = self.labels[i];
		// 0 - x
		// 1 - y
		// 2 - text
		labels.push([
			Math.round(label.x),
			Math.round(label.y),
			encodeURIComponent(encodeURIComponent(label.text))
		]);
	}
	data.push(labels);

	// META.
	data.push(Node._UID);

	// Return as string!
	var dataString = JSON.stringify(data);
	dataString = dataString.replace(/"/gi, "%22"); // and ONLY URIENCODE THE QUOTES
	dataString = dataString.substr(0, dataString.length-1) + "%5D";// also replace THE LAST CHARACTER
	return dataString;

};

self.deserialize = function(dataString){

	self.clear();

	var data = JSON.parse(dataString);

	// Get from array!
	var nodes = data[0];
	var edges = data[1];
	var labels = data[2];
	var UID = data[3];

	// Nodes
	for(var i=0;i<nodes.length;i++){
		var node = nodes[i];
		self.addNode({
			id: node[0],
			x: node[1],
			y: node[2],
			init: node[3],
			label: decodeURIComponent(node[4]),
			hue: node[5]
		});
	}

	// Edges
	for(var i=0;i<edges.length;i++){
		var edge = edges[i];
		var edgeConfig = {
			from: edge[0],
			to: edge[1],
			arc: edge[2],
			strength: edge[3]
		};
		if(edge[4]) edgeConfig.rotation=edge[4];
		self.addEdge(edgeConfig);
	}

	// Labels
	for(var i=0;i<labels.length;i++){
		var label = labels[i];
		self.addLabel({
			x: label[0],
			y: label[1],
			text: decodeURIComponent(label[2])
		});
	}

	// META.
	Node._UID = UID;

};

self.clear = function(){

	// Just kill ALL nodes.
	while(self.nodes.length>0){
		self.nodes[0].kill();
	}

	// Just kill ALL labels.
	while(self.labels.length>0){
		self.labels[0].kill();
	}
};



