// Mirror LOOPY Model.serialize() exactly, then round-trip via the loader path.
const enc = s => encodeURIComponent(encodeURIComponent(s));
const nodes = [
  [1,440,270,0.5,enc("Family Doctors"),3],
  [2,200,410,0.5,enc("Admin Burden"),1],
  [3,200,150,0.5,enc("Doctor Burnout"),0],
  [4,660,150,0.5,enc("ER Visits"),2],
  [5,880,300,0.5,enc("Bed Occupancy"),0],
  [6,660,430,0.5,enc("LTC Waitlist"),5],
];
const edges = [
  [2,3,40,1],    // Admin Burden -> Doctor Burnout (+)
  [3,1,40,-1],   // Doctor Burnout -> Family Doctors (-)
  [1,2,150,-1],  // Family Doctors -> Admin Burden (-)  closes reinforcing loop
  [1,4,-40,-1],  // Family Doctors -> ER Visits (-)
  [4,5,-40,1],   // ER Visits -> Bed Occupancy (+)
  [6,5,40,1],    // LTC Waitlist -> Bed Occupancy (+)
];
const labels = [
  [200,500,enc("Reinforcing loop")],
  [880,190,enc("The bottleneck")],
];
const data = [nodes,edges,labels,7];
let s = JSON.stringify(data);
s = s.replace(/"/gi,"%22");
s = s.substr(0,s.length-1)+"%5D";     // replace final ] with %5D
console.log("SERIALIZED:\n"+s+"\n");

// Round-trip: loader does decodeURIComponent(whole), then JSON.parse, then per-label decodeURIComponent
const loaded = decodeURIComponent(s);
const parsed = JSON.parse(loaded);
console.log("LABELS DECODE TO:", parsed[0].map(n=>decodeURIComponent(n[4])), parsed[2].map(l=>decodeURIComponent(l[2])));
console.log("EDGES:", JSON.stringify(parsed[1]));
console.log("VALID JSON round-trip: OK");
