@import 'tailwindcss';

@custom-variant dark (&:is(.dark *));
@plugin '@tailwindcss/typography';

@plugin 'tailwindcss-animate';

@theme {
  --breakpoint-xs: 30rem;

  --aspect-vertical: 9 / 16;

  --font-body: 'Noto Sans Variable', sans-serif;
  --font-heading: 'Crimson Pro Variable', sans-serif;

  --color-blue-100: hsl(210 100% 98%);
  --color-blue-200: hsl(210 68% 85%);
  --color-blue-300: hsl(210 68% 75%);
  --color-blue-400: hsl(210 68% 65%);
  --color-blue-500: hsl(210 68% 50%);
  --color-blue-600: hsl(210 68% 38%);
  --color-blue-700: hsl(210 68% 30%);
