interface GlossaryLookup {
  [term: string]: string;
}

/**
 * Links glossary terms in content while ignoring terms within specified HTML tags
 * @param content The HTML content to process
 * @param glossary Object mapping terms to their slugs
 * @param maxOccurrences Maximum number of times to link each term (default: 3)
 * @returns Content with glossary terms linked
 */
export function linkGlossaryTerms(
  content: string,
  glossary: GlossaryLookup
): string {
  const maxOccurrences: number = 2;
  const excludedTerms = ['scrum', 'agile', 'sprint', 'feedback', 'slack'];

  const excludedTags = [
    'img',
    'figure',
    'figcaption',
    'h1',
    'h2',
    'h3',
    'h4',
    'h5',
    'h6',
    'a',
  ];

  //Sort by length (longest terms first)
  const terms = Object.keys(glossary)
    .filter((term) => !excludedTerms.includes(term.toLowerCase()))
    .sort((a, b) => b.length - a.length);

  // Create a regex pattern for the terms
  const termsPattern = `\\b(${terms.join('|')})\\b`;

  // Split the content into segments: inside excluded tags and outside them
  const tagPattern = new RegExp(
    `<(${excludedTags.join('|')})(?:\\s[^>]*)?>(.*?)<\\/\\1>`,
    'gis'
  );

  let lastIndex = 0;
  let result = '';
  let match;

  // Track occurrences of each term
  const termOccurrences: Record<string, number> = {};

  // Process the content by segments
  while ((match = tagPattern.exec(content)) !== null) {
    // Process text before the tag
    const beforeTag = content.substring(lastIndex, match.index);
    result += processTextSegment(
      beforeTag,
      termsPattern,
      glossary,
      termOccurrences,
      maxOccurrences
    );

    // Add the tag content unchanged
    result += match[0];
    lastIndex = match.index + match[0].length;
  }

  // Process any remaining text after the last tag
  if (lastIndex < content.length) {
    const remainingText = content.substring(lastIndex);
    result += processTextSegment(
      remainingText,
      termsPattern,
      glossary,
      termOccurrences,
      maxOccurrences
    );
  }

  return result || content;
}

/**
 * Helper function to process a text segment and replace glossary terms
 */
function processTextSegment(
  text: string,
  termsPattern: string,
  glossary: GlossaryLookup,
  termOccurrences: Record<string, number>,
  maxOccurrences: number
): string {
  const regex = new RegExp(termsPattern, 'gi');

  return text.replace(regex, (match) => {
    const termLower = match.toLowerCase();
    const slug = glossary[termLower]; // Find slug in glossary (case insensitive)

    if (slug) {
      // Initialize counter if not exists
      if (termOccurrences[termLower] === undefined) {
        termOccurrences[termLower] = 0;
      }

      // Check if we've reached the maximum occurrences
      if (termOccurrences[termLower] < maxOccurrences) {
        termOccurrences[termLower]++;
        return `<a href="/glossary/${slug}/" class="glossary-link">${match}</a>`;
      }
    }

    return match; // Return the match unchanged if no slug is found or max occurrences reached
  });
}

