  return text.replace(regex, (match) => {
    const termLower = match.toLowerCase();
    const slug = glossary[termLower]; // Find slug in glossary (case insensitive)

    if (slug) {
      // Initialize counter if not exists
      if (termOccurrences[termLower] === undefined) {
        termOccurrences[termLower] = 0;
      }

      // Check if we've reached the maximum occurrences
      if (termOccurrences[termLower] < maxOccurrences) {
        termOccurrences[termLower]++;
        return `<a href="/glossary/${slug}/" class="glossary-link">${match}</a>`;
      }
    }

    return match; // Return the match unchanged if no slug is found or max occurrences reached
  });
}

